import{z as T,x as n,o,c as h,q as t,j as l,D as e,d as E,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Tree of Thoughts","description":"","frontmatter":{"title":"Tree of Thoughts","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tree-of-thoughts.md","filePath":"llm/tree-of-thoughts.md","lastUpdated":1791413859000}'),B={name:"llm/tree-of-thoughts.md"};function A(p,a,d,m,u,f){const r=n("Mermaid");return o(),h("div",null,[a[2]||(a[2]=t('<h1 id="tree-of-thoughts" tabindex="-1">Tree of Thoughts <a class="header-anchor" href="#tree-of-thoughts" aria-label="Permalink to &quot;Tree of Thoughts&quot;">​</a></h1><div class="epigraph"><p>把问题求解看成在思维树上的有意搜索：每一步考虑多个不同的推理分支，并自我评估再决定扩展哪一条。</p><footer>—— Yao et al., Tree of Thoughts: Deliberate Problem Solving with Large Language Models, NeurIPS 2023</footer></div><p><a href="/llm/chain-of-thought">思维链</a>是一条从根到叶的路径：<a href="/llm/self-consistency">自洽</a>是许多独立路径再在终点投票。两者都不在 <em>中间状态</em> 上分支与剪枝。Yao 等人把「思维」定义成可评估的中间对象（一个部分公式、一段计划、一格填字），用语言模型做三件事：提出若干后继思维、评估当前节点、按广度或深度优先扩展。这就是思维树（Tree of Thoughts, ToT）。它把经典树搜索接到生成模型上，是测试时在深度方向花钱，而不是只在独立样本的宽度上花钱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单链 CoT 不能回溯。Game of 24 一类任务在某步选错四个数的组合，后面再「仔细想」也救不回来，因为前缀已经锁死。自洽可以多开几条完整链，但每条链内部仍然贪婪，预算浪费在重复走到同一死胡同。需要把搜索状态从「整道题的完整解答」改成「部分解答」，使算法能在中间节点比较、丢弃、换分支。</p><p><span class="marginnote">直觉类比：CoT 是「一条道走到黑」；自洽是「多派几个人各走各的、终点对答案」；ToT 是「一个人走迷宫带铅笔——走进死路就退回来，把叉擦掉换条路」。那块橡皮（可回退的中间状态）才是 ToT 的本质新增。</span></p>',6)),(o(),l(i,null,{default:e(()=>[s(r,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20COT%5B%22%E5%8D%95%E9%93%BE%20CoT%22%5D%0A%20%20%20%20C1%5B%22%E4%B8%80%E6%9D%A1%E8%B7%AF%E5%BE%84%E8%B5%B0%E5%88%B0%E5%BA%95%22%5D%20--%3E%20C2%5B%22%E5%89%8D%E7%BC%80%E9%94%81%E6%AD%BB%EF%BC%8C%E6%97%A0%E6%B3%95%E5%9B%9E%E9%80%80%22%5D%0A%20%20end%0A%20%20subgraph%20SC%5B%22%E8%87%AA%E6%B4%BD%22%5D%0A%20%20%20%20S1%5B%22%E5%A4%9A%E6%9D%A1%E7%8B%AC%E7%AB%8B%E5%AE%8C%E6%95%B4%E9%93%BE%22%5D%20--%3E%20S2%5B%22%E5%8F%AA%E5%9C%A8%E7%BB%88%E7%82%B9%E6%8A%95%E7%A5%A8%EF%BC%8C%E4%B8%AD%E9%80%94%E4%B8%8D%E5%89%AA%E6%9E%9D%22%5D%0A%20%20end%0A%20%20subgraph%20TOT%5B%22%E6%80%9D%E7%BB%B4%E6%A0%91%22%5D%0A%20%20%20%20T1%5B%22%E9%83%A8%E5%88%86%E8%A7%A3%E5%BD%93%E8%8A%82%E7%82%B9%EF%BC%8C%E5%85%B1%E4%BA%AB%E5%89%8D%E7%BC%80%22%5D%20--%3E%20T2%5B%22%E4%B8%AD%E9%80%94%E8%AF%84%E4%BC%B0%EF%BC%9A%E5%89%AA%E6%9E%9D%E3%80%81%E5%9B%9E%E6%BA%AF%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>ToT 要回答的是：思维的 <em>粒度</em> 如何定义，以及用什么分数决定扩展。粒度过细，树的分支因子爆炸，每步评估变成对标点打分；粒度过粗，退回自洽。评估器若只是模型自己说「看起来不错」，搜索会朝流畅的假推理走，与弱核对器上的 Best-of-N 是同一失败模式。</p><h3 id="中间状态必须可评估" tabindex="-1">中间状态必须可评估 <a class="header-anchor" href="#中间状态必须可评估" aria-label="Permalink to &quot;中间状态必须可评估&quot;">​</a></h3><p>一个节点 \\(s\\) 要满足：能从 \\(s\\) 生成有限个后继；能给 \\(s\\) 一个标量或分类判断（可行 / 有希望 / 不可能）；失败节点可以丢弃而不必生成到终点。Game of 24 里 \\(s\\) 是当前剩余数字与已写算式；创意写作里 \\(s\\) 可以是段落提纲；填字里 \\(s\\) 是部分填满的格。若任务给不出这种 \\(s\\)，ToT 没有搜索空间，不要硬把句子按句号切开当节点。</p><p><span class="marginnote">ToT 不是一种提示套话。只在用户消息里写「请用思维树思考」却不做生成—评估—搜索循环，仍然是单链 CoT。论文的方法是算法加提示，缺宿主侧的树调度就不成立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宿主维护一棵树。对叶子或前沿节点，用提示让模型生成 \\(k\\) 个后继思维（可采样或提示「列出三个不同方案」）。再用独立提示（或同一模型的另一次调用）评估节点：分类（sure / maybe / impossible）或打分。搜索策略可以是 BFS：每层保留分数最高的 \\(b\\) 个节点；或 DFS：沿最有希望的分支走，失败则回溯。达到终止条件（得到合法解、深度上限、预算用尽）后返回最佳叶。生成与评估所用的提示必须按任务写，没有与任务无关的万能 ToT 模板。</p><p>评估可以是规则：Game of 24 用算术合法性；有测试的代码用单测。规则评估比模型自评更值得优先。模型自评适合难以写规则但人类能一眼看出来的部分解。评估提示应要求只看当前节点、不要把尚未生成的后续当证据，否则评估器会「预支」成功。</p>',7)),(o(),l(i,null,{default:e(()=>[s(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B9%EF%BC%9A%E9%A2%98%E9%9D%A2%22%5D%20--%3E%20G%5B%22%E7%94%9F%E6%88%90%20k%20%E4%B8%AA%E5%90%8E%E7%BB%A7%E6%80%9D%E7%BB%B4%22%5D%0A%20%20G%20--%3E%20E%5B%22%E8%AF%84%E4%BC%B0%E8%8A%82%E7%82%B9%22%5D%0A%20%20E%20--%3E%20PRUNE%5B%22%E5%89%AA%E6%9E%9D%20%2F%20%E4%BF%9D%E7%95%99%20top-b%22%5D%0A%20%20PRUNE%20--%3E%20D%7B%22%E7%BB%88%E6%AD%A2%3F%22%7D%0A%20%20D%20--%3E%7C%E5%90%A6%7C%20G%0A%20%20D%20--%3E%7C%E6%98%AF%7C%20ANS%5B%22%E6%9C%80%E4%BD%B3%E5%8F%B6%E8%8A%82%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h3 id="生成、评估与搜索三条提示" tabindex="-1">生成、评估与搜索三条提示 <a class="header-anchor" href="#生成、评估与搜索三条提示" aria-label="Permalink to &quot;生成、评估与搜索三条提示&quot;">​</a></h3><p>ToT 至少三套提示。生成器：条件于题面与当前路径，列出互不相同的下一步。评估器：条件于题面与候选节点，输出判断。可选的选择器：在 BFS 的一层里做两两比较。把三套提示揉成一次生成，模型会既当运动员又当裁判，分数向已写内容倾斜。实现上应分次调用，并固定评估器温度接近 0，生成器温度略高以保分支多样性。</p><p>与 <a href="/llm/mcts-llm">MCTS</a> 的差别：原文 ToT 用 BFS/DFS 加启发式评估，没有 UCT 的探索项，也没有模拟到终局的 rollout 统计。后来有人把 ToT 的节点接到 MCTS 或过程奖励上，那是扩展，评测时要分开。与过程奖励引导的束搜索相比，ToT 的评估器往往是即时提示的语言模型，而不是单独训练的 PRM；便宜，但校准更差。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ToT 把测试时计算花在 <em>决策点</em> 上。每个节点的生成是局部的，评估提供剪枝信号，使预算从无望前缀上收回。这要求评估器的假阴性不太高：错杀正确部分解，后面再宽的搜索也救不回。假阳性则让树在花哨但已错的节点上浪费深度。因此 ToT 的上限仍由评估质量决定，生成器只负责覆盖。</p><p><span class="marginnote">为什么重要：评估器的两类错误代价不对称。假阳性只是浪费预算——多评估几个没希望的节点；假阴性是错杀——被剪掉的子树永远不会被重新访问，正确答案直接消失。所以校准评估器时宁可松一点，也别剪太狠。</span></p><p><span class="marginnote">数字实例：取分支因子 \\(k=5\\)、每层保留 \\(b=5\\)、深度 3，树最多有 \\(5+25+125=155\\) 个候选节点要评估；若每次评估是一次模型调用，一次提问的实际开销可能是普通 CoT 的上百倍——报准确率时必须连 \\((k,b,\\) 深度\\()\\) 一起报。</span></p><p>相对自洽：自洽的多样性是完整轨迹级的，中间不共享前缀计算，也不能在第 3 步发现第 2 步该回退。ToT 共享从根到当前节点的前缀，回溯有意义。代价是实现复杂、延迟由深度乘宽度放大，且提示与状态表示都是任务相关的——换任务几乎要重写。不要指望把 GSM8K 的 CoT 示范换成「ToT」四个字母就能得到树搜索。</p><p><span class="marginnote">分支因子 \\(k\\) 与保留宽度 \\(b\\) 是费用旋钮。报告准确率而不报 \\((k,b,\\) 深度上限 \\()\\)，等于没报方法。线上还应设墙钟与 token 预算，避免 DFS 在死胡同里走完最大深度。</span></p><h3 id="自评会偏好流畅的假推理" tabindex="-1">自评会偏好流畅的假推理 <a class="header-anchor" href="#自评会偏好流畅的假推理" aria-label="Permalink to &quot;自评会偏好流畅的假推理&quot;">​</a></h3><p>语言模型评估器喜欢读起来完整的节点。把错误公式写得像教科书，分数可以高于一句正确但难看的中间式。缓解：能执行则执行；不能执行则让评估器只做分类并要求指出具体缺陷；或对同一节点独立评估多次再投票。不要用生成器自己的 \\(\\log\\pi\\) 当 ToT 分数——那是在做束搜索，目标又变回似然。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ToT 适合有清晰部分解、可定义合法性、搜索深度不深的谜题与规划。开放域长文、单跳检索、参数已从用户话填全的一次函数调用，不值得起树。评估器若必须用大模型且每节点多次调用，费用可能超过「更大的基座模型 + 自洽」。工程上常先用规则剪枝，再用模型在存活节点里排序。</p><p>状态表示要能放进提示：过大的棋盘、过长的部分程序，评估提示会丢细节。需要聚合多条部分解时，树不够用，应看<a href="/llm/graph-of-thoughts">思维图</a>。ToT 也不替代工具：环境反馈应写成节点上的观察，而不是让模型在思维里假装执行。与 <a href="/llm/react">ReAct</a> 结合时，树的边可以是动作，节点是观察后的状态，但那已经是搜索式智能体，提示与调度都更重。</p><p><span class="marginnote">论文中的 Game of 24、填字、创意写作是展示搜索结构的任务，不是通用基准。把 ToT 搬到产品 FAQ 上却没有可评估的中间状态，通常只是多付了几次评估调用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>思维树把中间思维当成节点，用生成、评估、BFS/DFS 做有回溯的搜索。</li><li>它是算法加任务相关提示，不是一句「请用 ToT」的套话。</li><li>评估质量决定剪枝是否正确；规则与执行应优先于模型自评。</li><li>相对单链与自洽，它在中间状态上花钱，实现与费用都更重。</li><li>粒度、分支因子、深度上限必须按任务设计，并与准确率一起报。</li><li>出处：Yao et al., <em>Tree of Thoughts: Deliberate Problem Solving with Large Language Models</em>, NeurIPS 2023。</li></ul>',17))])}const C=T(B,[["render",A]]);export{c as __pageData,C as default};
